// 1. Function Pointer Precedence
// ( ) binds tighter than *
// `fp` is a pointer to a function returning int
int (*fp)(int, int);

// `f_ptr` is a function returning an int*
int* f_ptr(int, int);

// Assignment
int adder(int a, int b) { return a + b; }
fp = adder;


// 2. Array vs Pointer Precedence
// [] binds tighter than *
// `ptr_arr` is an array of 5 pointers to int
int* ptr_arr[5];

// `arr_ptr` is a pointer to an array of 5 ints
int (*arr_ptr)[5];

int data[1][5];
arr_ptr = data;


// 3. Simplifying Complex Declarations (typedef)
// Defines the function signature type
typedef int (*BinaryFnPtr)(int, int);

// Usage is much cleaner
int subtract(int a, int b) { return a - b; }
BinaryFnPtr op = subtract;
int result = op(20, 10);
